import{_ as a,o as n,c as e,a3 as l}from"./chunks/framework.CqzWVxDX.js";const p="/ems_simulate/assets/modbus-message.C83nX28b.png",h=JSON.parse('{"title":"Modbus 报文查看","description":"","frontmatter":{},"headers":[],"relativePath":"guide/protocols/modbus/packet-view.md","filePath":"guide/protocols/modbus/packet-view.md","lastUpdated":1786981506000}'),i={name:"guide/protocols/modbus/packet-view.md"};function t(r,s,o,d,c,b){return n(),e("div",null,[...s[0]||(s[0]=[l('<h1 id="modbus-报文查看" tabindex="-1">Modbus 报文查看 <a class="header-anchor" href="#modbus-报文查看" aria-label="Permalink to &quot;Modbus 报文查看&quot;">​</a></h1><h2 id="进入报文查看" tabindex="-1">进入报文查看 <a class="header-anchor" href="#进入报文查看" aria-label="Permalink to &quot;进入报文查看&quot;">​</a></h2><ol><li>在左侧设备树中选中 Modbus 设备；</li><li>点击右侧上方的&quot;<strong>报文</strong>&quot;图标；</li><li>在弹出的窗口中实时查看通讯帧，支持暂停刷新、按方向/从机筛选、查看报文详情与原始字节定位。</li></ol><p><img src="'+p+`" alt=""></p><h2 id="modbus-tcp-帧结构" tabindex="-1">Modbus TCP 帧结构 <a class="header-anchor" href="#modbus-tcp-帧结构" aria-label="Permalink to &quot;Modbus TCP 帧结构&quot;">​</a></h2><p>TCP 模式下报文由 <strong>MBAP 头 + PDU</strong> 组成：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────┬──────────────┬──────────┬──────────────┬──────────────────┐</span></span>
<span class="line"><span>│ 事务标识符     │ 协议标识符     │ 长度      │ 单元标识符     │ PDU（功能码+数据） │</span></span>
<span class="line"><span>│ 2 字节        │ 2 字节       │ 2 字节   │ 1 字节       │ N 字节            │</span></span>
<span class="line"><span>└──────────────┴──────────────┴──────────┴──────────────┴──────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>事务标识符</td><td>客户端生成，用于匹配请求与响应（响应回显同值）</td></tr><tr><td>协议标识符</td><td>Modbus 固定为 <code>0x0000</code></td></tr><tr><td>长度</td><td>后续（单元标识符 + PDU）的字节数</td></tr><tr><td>单元标识符</td><td>从站地址（多从站网关时使用）</td></tr></tbody></table><h2 id="modbus-rtu-帧结构" tabindex="-1">Modbus RTU 帧结构 <a class="header-anchor" href="#modbus-rtu-帧结构" aria-label="Permalink to &quot;Modbus RTU 帧结构&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────┬──────────┬──────────────┬──────────┐</span></span>
<span class="line"><span>│ 从站地址  │ 功能码    │ 数据          │ CRC16    │</span></span>
<span class="line"><span>│ 1 字节   │ 1 字节   │ N 字节        │ 2 字节   │</span></span>
<span class="line"><span>└──────────┴──────────┴──────────────┴──────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><ul><li>从站地址：1~247（0 为广播地址）；</li><li>CRC16：从从站地址到数据末尾的循环冗余校验；</li><li>帧间间隔 ≥ 3.5 个字符时间，用于帧定界。</li></ul><h2 id="请求-响应示例" tabindex="-1">请求 / 响应示例 <a class="header-anchor" href="#请求-响应示例" aria-label="Permalink to &quot;请求 / 响应示例&quot;">​</a></h2><p><strong>读保持寄存器（功能码 03）请求</strong>（从站 1，起始地址 0x0000，读 2 个寄存器）：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>01 03 00 00 00 02 C4 0B</span></span>
<span class="line"><span>│  │  │    │    │    └─ CRC16</span></span>
<span class="line"><span>│  │  │    │    └────── 寄存器数量 = 2</span></span>
<span class="line"><span>│  │  │    └─────────── 起始地址 = 0x0000</span></span>
<span class="line"><span>│  │  └──────────────── 功能码 = 03</span></span>
<span class="line"><span>│  └─────────────────── 从站地址 = 1</span></span>
<span class="line"><span>└────────────────────── 帧起始</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><strong>响应</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>01 03 04 00 0A 00 14 ...</span></span>
<span class="line"><span>│  │  │  │    │</span></span>
<span class="line"><span>│  │  │  │    └──── 寄存器2 = 0x0014（按解析码解释）</span></span>
<span class="line"><span>│  │  │  └───────── 寄存器1 = 0x000A</span></span>
<span class="line"><span>│  │  └──────────── 数据字节数 = 4（2 个寄存器）</span></span>
<span class="line"><span>│  └─────────────── 功能码 = 03</span></span>
<span class="line"><span>└────────────────── 从站地址 = 1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h2 id="报文解析功能" tabindex="-1">报文解析功能 <a class="header-anchor" href="#报文解析功能" aria-label="Permalink to &quot;报文解析功能&quot;">​</a></h2><p>EMS Simulate 对原始十六进制报文自动解析，展示：</p><ul><li><strong>时间记录</strong>：发送 / 接收时间；</li><li><strong>方向标记</strong>：TX（发送）/ RX（接收）；</li><li><strong>字段解析</strong>：功能码、起始地址、寄存器数量、字节数、寄存器原始值；</li><li><strong>值解释</strong>：按测点配置的解析码将原始值解释为浮点/整数等，并应用系数换算；</li><li><strong>异常帧</strong>：功能码最高位置 1（如 <code>0x83</code>）表示异常，附异常码（非法地址/非法数据等）。</li></ul><h2 id="交互流程" tabindex="-1">交互流程 <a class="header-anchor" href="#交互流程" aria-label="Permalink to &quot;交互流程&quot;">​</a></h2><ol><li>客户端发起请求（事务 ID + 功能码 + 地址 + 数量）；</li><li>服务端处理并回送响应帧（事务 ID 回显）；</li><li>读取类请求返回数据区内容，写入类请求返回写入确认。</li></ol><h2 id="排查技巧" tabindex="-1">排查技巧 <a class="header-anchor" href="#排查技巧" aria-label="Permalink to &quot;排查技巧&quot;">​</a></h2><ul><li>长时间无响应：先看 TCP 是否建立（连接超时参数），再看从站地址与功能码；</li><li>数据值异常：核对解析码字节序与系数；</li><li>偶发失败：查看命令超时与重试次数，检查网络抖动或从站负载；</li><li>结合&quot;报文详情&quot;的逐字节定位，快速判断是哪一段数据异常。</li></ul>`,23)])])}const m=a(i,[["render",t]]);export{h as __pageData,m as default};
